styles:
.io-scroller {
      height: 280px;
      overflow: auto;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg);
      padding: 1rem;
      scroll-behavior: smooth;
    }
    .io-spacer {
      height: 120px;
      display: grid;
      place-items: center;
      color: var(--is-text-dim);
      font-size: 0.8rem;
      border: 1px dashed var(--is-border-soft);
      border-radius: var(--is-radius-sm);
      margin-bottom: 0.75rem;
    }
    .io-card {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.1rem;
      margin-bottom: 0.75rem;
      border-radius: var(--is-radius);
      border: 1px solid var(--is-border);
      background: var(--is-bg-elev);
      color: var(--is-text-soft);
      opacity: 0.45;
      transform: translateY(10px);
      transition: opacity 280ms ease, transform 280ms ease, background 280ms ease, border-color 280ms ease, color 280ms ease;
    }
    .io-card.is-in {
      opacity: 1;
      transform: none;
      background: color-mix(in srgb, var(--is-color-brand) 14%, var(--is-bg-elev));
      border-color: color-mix(in srgb, var(--is-color-brand) 45%, var(--is-border));
      color: var(--is-text);
    }
    .io-card.is-in .io-badge {
      background: var(--is-brand-soft);
      color: var(--is-brand-text);
    }
    .io-badge {
      flex: 0 0 auto;
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      padding: 0.25em 0.55em;
      border-radius: 999px;
      background: var(--is-control-bg);
      color: var(--is-text-dim);
    }
    .io-uses {
      display: grid;
      gap: 0.65rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .io-uses li {
      display: grid;
      grid-template-columns: 1.5rem 1fr;
      gap: 0.55rem;
      align-items: start;
      color: var(--is-text-soft);
      font-size: 0.92rem;
      line-height: 1.45;
    }
    .io-uses is-icon {
      width: 1.15em;
      height: 1.15em;
      color: var(--is-accent);
      margin-top: 0.15em;
    }
    .io-diagram {
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      gap: 0.75rem;
      align-items: center;
      margin: 1rem 0 0;
    }
    .io-diagram__pane {
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius-sm);
      background: var(--is-bg);
      padding: 0.75rem;
      min-height: 7rem;
      position: relative;
    }
    .io-diagram__pane strong {
      display: block;
      font-size: 0.72rem;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--is-text-dim);
      margin-bottom: 0.5rem;
    }
    .io-diagram__box {
      height: 1.6rem;
      border-radius: 4px;
      margin-bottom: 0.35rem;
      background: var(--is-control-bg);
      border: 1px solid var(--is-border-soft);
    }
    .io-diagram__box.on {
      background: color-mix(in srgb, var(--is-color-success) 35%, var(--is-control-bg));
      border-color: var(--is-color-success);
    }
    .io-diagram__box.off { opacity: 0.35; }
    .io-diagram__viewport {
      outline: 2px dashed var(--is-accent);
      outline-offset: -6px;
      border-radius: inherit;
    }
    .io-diagram__arrow {
      color: var(--is-text-dim);
      font-size: 1.4rem;
    }
    @media (max-width: 720px) {
      .io-diagram { grid-template-columns: 1fr; }
      .io-diagram__arrow { transform: rotate(90deg); justify-self: center; }
    }
